/**
 * Translate a crop name into the requested language.
 */
export function tCrop(cropName, lang = 'en') {
  if (!cropName) return '';
  const langDict = CROP_TRANSLATIONS[lang] || CROP_TRANSLATIONS.en;
  return langDict[cropName] || CROP_TRANSLATIONS.en[cropName] || cropName;
}

/**
 * Translate a crop residue name into the requested language.
 */
export function tResidue(residueName, lang = 'en') {
  if (!residueName) return '';
  const langDict = RESIDUE_TRANSLATIONS[lang] || RESIDUE_TRANSLATIONS.en;
  return langDict[residueName] || RESIDUE_TRANSLATIONS.en[residueName] || residueName;
}

